-- Admin module idents and action names in English (the lists in Admin\LegacyUrls): permissions of users and
-- roles and the change log. Old URLs keep working through LegacyUrls; the stored idents must be the current ones.
UPDATE ka_uzivatele_prava SET ident_modulu = CASE ident_modulu WHEN 'stranky' THEN 'pages' WHEN 'novinky' THEN 'news' WHEN 'kolekce' THEN 'collections' WHEN 'poptavky' THEN 'enquiries' WHEN 'odberatele' THEN 'subscribers' WHEN 'kategorie' THEN 'categories' WHEN 'stitky' THEN 'tags' WHEN 'intergal' THEN 'media' WHEN 'vzhled' THEN 'appearance' WHEN 'casti' THEN 'parts' WHEN 'komponenty' THEN 'components' WHEN 'popupy' THEN 'popups' WHEN 'role' THEN 'roles' WHEN 'stat' THEN 'stats' WHEN 'presmerovani' THEN 'redirects' WHEN 'protokol' THEN 'changelog' WHEN 'prenos' THEN 'transfer' WHEN 'rozsireni' THEN 'extensions' WHEN 'config' THEN 'settings' ELSE ident_modulu END WHERE ident_modulu IN ('stranky', 'novinky', 'kolekce', 'poptavky', 'odberatele', 'kategorie', 'stitky', 'intergal', 'vzhled', 'casti', 'komponenty', 'popupy', 'role', 'stat', 'presmerovani', 'protokol', 'prenos', 'rozsireni', 'config');
UPDATE ka_role SET moduly = TRIM(BOTH ',' FROM REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CONCAT(',', moduly, ','), ',stranky,', ',pages,'), ',novinky,', ',news,'), ',kolekce,', ',collections,'), ',poptavky,', ',enquiries,'), ',odberatele,', ',subscribers,'), ',kategorie,', ',categories,'), ',stitky,', ',tags,'), ',intergal,', ',media,'), ',vzhled,', ',appearance,'), ',casti,', ',parts,'), ',komponenty,', ',components,'), ',popupy,', ',popups,'), ',role,', ',roles,'), ',stat,', ',stats,'), ',presmerovani,', ',redirects,'), ',protokol,', ',changelog,'), ',prenos,', ',transfer,'), ',rozsireni,', ',extensions,'), ',config,', ',settings,')) WHERE moduly <> '';
UPDATE ka_protokol SET modul = CASE modul WHEN 'stranky' THEN 'pages' WHEN 'novinky' THEN 'news' WHEN 'kolekce' THEN 'collections' WHEN 'poptavky' THEN 'enquiries' WHEN 'odberatele' THEN 'subscribers' WHEN 'kategorie' THEN 'categories' WHEN 'stitky' THEN 'tags' WHEN 'intergal' THEN 'media' WHEN 'vzhled' THEN 'appearance' WHEN 'casti' THEN 'parts' WHEN 'komponenty' THEN 'components' WHEN 'popupy' THEN 'popups' WHEN 'role' THEN 'roles' WHEN 'stat' THEN 'stats' WHEN 'presmerovani' THEN 'redirects' WHEN 'protokol' THEN 'changelog' WHEN 'prenos' THEN 'transfer' WHEN 'rozsireni' THEN 'extensions' WHEN 'config' THEN 'settings' ELSE modul END WHERE modul IN ('stranky', 'novinky', 'kolekce', 'poptavky', 'odberatele', 'kategorie', 'stitky', 'intergal', 'vzhled', 'casti', 'komponenty', 'popupy', 'role', 'stat', 'presmerovani', 'protokol', 'prenos', 'rozsireni', 'config');
UPDATE ka_protokol SET akce = CASE akce WHEN 'aktualizuj' THEN 'update' WHEN 'asistent' THEN 'assistant' WHEN 'automaticky' THEN 'automatic' WHEN 'detail' THEN 'detail' WHEN 'duplikuj' THEN 'duplicate' WHEN 'duplikuj_polozku' THEN 'duplicate_item' WHEN 'hledej_json' THEN 'search_json' WHEN 'hromadne' THEN 'bulk' WHEN 'koncept' THEN 'draft' WHEN 'nahled' THEN 'preview' WHEN 'nahradit' THEN 'replace' WHEN 'nahraj' THEN 'upload' WHEN 'nastaveni' THEN 'settings' WHEN 'novy' THEN 'new' WHEN 'obnov' THEN 'restore' WHEN 'obnov_verzi' THEN 'restore_version' WHEN 'obnov_zalohu' THEN 'restore_backup' WHEN 'obrazky' THEN 'images' WHEN 'odkaz_hesla' THEN 'password_link' WHEN 'odkazy' THEN 'links' WHEN 'polozka' THEN 'item' WHEN 'polozky' THEN 'items' WHEN 'porovnej' THEN 'compare' WHEN 'poznamka' THEN 'note' WHEN 'preloz' THEN 'translate' WHEN 'prepni' THEN 'toggle' WHEN 'priloha' THEN 'attachment' WHEN 'prubeh' THEN 'progress' WHEN 'revize' THEN 'versions' WHEN 'sablona' THEN 'template' WHEN 'seznam' THEN 'listing' WHEN 'slozka' THEN 'folder' WHEN 'slozka_smaz' THEN 'folder_delete' WHEN 'smaz' THEN 'delete' WHEN 'smaz_export' THEN 'delete_export' WHEN 'smaz_log' THEN 'delete_log' WHEN 'smaz_natrvalo' THEN 'delete_permanently' WHEN 'smaz_polozku' THEN 'delete_item' WHEN 'smaz_soubor' THEN 'delete_file' WHEN 'smaz_zalohu' THEN 'delete_backup' WHEN 'spust' THEN 'run' WHEN 'stahni' THEN 'download' WHEN 'stahni_zalohu' THEN 'download_backup' WHEN 'stav' THEN 'status' WHEN 'stavba_ai_sekce' THEN 'build_ai_section' WHEN 'stavba_ai_text' THEN 'build_ai_text' WHEN 'stavba_obnov' THEN 'build_restore' WHEN 'stavba_publikuj' THEN 'build_publish' WHEN 'stavba_revize' THEN 'build_versions' WHEN 'stavba_sdilet' THEN 'build_share' WHEN 'stavba_sekce' THEN 'build_section' WHEN 'stavba_smaz_sekci' THEN 'build_delete_section' WHEN 'stavba_text' THEN 'build_text' WHEN 'stavba_trida' THEN 'build_class' WHEN 'stavba_uloz' THEN 'build_save' WHEN 'stavba_uloz_sekci' THEN 'build_save_section' WHEN 'stavba_zahod' THEN 'build_discard' WHEN 'stavitel' THEN 'builder' WHEN 'synchronizuj' THEN 'sync' WHEN 'test_posty' THEN 'test_mail' WHEN 'tokeny' THEN 'tokens' WHEN 'tokeny_import' THEN 'tokens_import' WHEN 'uloz' THEN 'save' WHEN 'uloz_polozku' THEN 'save_item' WHEN 'uloz_popis' THEN 'save_caption' WHEN 'uloz_text' THEN 'save_text' WHEN 'uloz_variantu' THEN 'save_variant' WHEN 'varianta' THEN 'variant' WHEN 'vyber' THEN 'select' WHEN 'vycisti' THEN 'clear' WHEN 'vynuluj' THEN 'reset' WHEN 'vypis' THEN 'list' WHEN 'z_prvku' THEN 'from_element' WHEN 'zaloha_medii' THEN 'media_backup' WHEN 'zalohuj' THEN 'backup' WHEN 'zaloz' THEN 'create' WHEN 'zkontroluj' THEN 'check' WHEN 'znovu' THEN 'retry' WHEN 'heslo' THEN 'password' WHEN 'ucet' THEN 'account' WHEN 'pruvodce_skryt' THEN 'hide_first_steps' ELSE akce END WHERE akce IN ('aktualizuj', 'asistent', 'automaticky', 'detail', 'duplikuj', 'duplikuj_polozku', 'hledej_json', 'hromadne', 'koncept', 'nahled', 'nahradit', 'nahraj', 'nastaveni', 'novy', 'obnov', 'obnov_verzi', 'obnov_zalohu', 'obrazky', 'odkaz_hesla', 'odkazy', 'polozka', 'polozky', 'porovnej', 'poznamka', 'preloz', 'prepni', 'priloha', 'prubeh', 'revize', 'sablona', 'seznam', 'slozka', 'slozka_smaz', 'smaz', 'smaz_export', 'smaz_log', 'smaz_natrvalo', 'smaz_polozku', 'smaz_soubor', 'smaz_zalohu', 'spust', 'stahni', 'stahni_zalohu', 'stav', 'stavba_ai_sekce', 'stavba_ai_text', 'stavba_obnov', 'stavba_publikuj', 'stavba_revize', 'stavba_sdilet', 'stavba_sekce', 'stavba_smaz_sekci', 'stavba_text', 'stavba_trida', 'stavba_uloz', 'stavba_uloz_sekci', 'stavba_zahod', 'stavitel', 'synchronizuj', 'test_posty', 'tokeny', 'tokeny_import', 'uloz', 'uloz_polozku', 'uloz_popis', 'uloz_text', 'uloz_variantu', 'varianta', 'vyber', 'vycisti', 'vynuluj', 'vypis', 'z_prvku', 'zaloha_medii', 'zalohuj', 'zaloz', 'zkontroluj', 'znovu', 'heslo', 'ucet', 'pruvodce_skryt');
